function distributions(history,window,count){const recent=history.slice(-window),experts=Array.from({length:7},()=>Array(49).fill(1));history.forEach((d,i)=>{for(const n of d.numbers){experts[1][n-1]++;experts[3][n-1]+=Math.pow(.5,(history.length-1-i)/12);}});for(const d of recent)for(const n of d.numbers)experts[2][n-1]++;const anchors=best(normalize(experts[2])).slice(0,3);for(const d of recent)for(const n of d.numbers)experts[4][n-1]+=1+d.numbers.filter(x=>x!==n&&anchors.includes(x)).length/3;experts[5].fill(20);for(const d of history)for(const n of d.numbers)experts[5][n-1]++;experts[6].fill(20);const last=history.at(-1);for(let i=1;i<history.length;i++){const overlap=history[i-1].numbers.filter(n=>last.numbers.includes(n)).length;for(const n of history[i].numbers)experts[6][n-1]+=overlap/6;}return {numbers:experts.slice(0,count).map(normalize),recent};}
